// Top Class product photos, grouped by pack format (folder under public/topclass/).
// Every image exists in two widths, generated by scripts/optimize-topclass-images.mjs:
//   /topclass/<path>.webp      1600px
//   /topclass/<path>-640.webp   640px

export interface TcImage {
  path: string;
  label: string;
}

export const tcSrc = (path: string) => `/topclass/${path}.webp`;
export const tcSmall = (path: string) => `/topclass/${path}-640.webp`;
export const tcSrcset = (path: string) => `${tcSmall(path)} 640w, ${tcSrc(path)} 1600w`;

